mapper.sql:
districts AS MATERIALIZED ( SELECT g.district_code, g.geom, ST_XMin(g.geom) AS xmin, ST_XMax(g.geom) AS xmax, ST_YMin(g.geom) AS ymin, ST_YMax(g.geom) AS ymax FROM ( SELECT refs.district_code, ST_Transform(ST_GeomFromEWKB(decode(refs.scope_hex, 'hex')), #{sourceSrid}) AS geom FROM (VALUES
(#{district.code}::text, #{district.scopeEwkbHex}::text)
) AS refs(district_code, scope_hex) ) AS g )
